import pandas as pd
import numpy as np


def _plans_equal(a, b):
    a_null = pd.isna(a)
    b_null = pd.isna(b)
    if a_null and b_null:
        return True
    if a_null != b_null:
        return False
    return a == b


def run(inputs):
    dim = inputs["DIM_ACCOUNT"].copy()
    stg = inputs["STG_ACCOUNT"].copy()

    # normalize date columns to Timestamp (NaT for null) for safe comparisons
    dim["eff_start_date"] = pd.to_datetime(dim["eff_start_date"])
    dim["eff_end_date"] = pd.to_datetime(dim["eff_end_date"])
    stg["update_date"] = pd.to_datetime(stg["update_date"])

    # build working state: account_id -> list of version dicts
    account_versions = {}
    for _, row in dim.iterrows():
        acc = row["account_id"]
        versions = account_versions.setdefault(acc, [])
        versions.append(
            {
                "plan": row["plan"],
                "eff_start_date": row["eff_start_date"],
                "eff_end_date": row["eff_end_date"] if not pd.isna(row["eff_end_date"]) else None,
                "is_current": int(row["is_current"]),
            }
        )

    # order staged records by account_id, update_date ascending
    stg_sorted = stg.sort_values(by=["account_id", "update_date"], kind="stable")

    for _, srow in stg_sorted.iterrows():
        acc = srow["account_id"]
        s_plan = srow["plan"]
        s_date = srow["update_date"]

        versions = account_versions.get(acc)

        if not versions:
            account_versions[acc] = [
                {
                    "plan": s_plan,
                    "eff_start_date": s_date,
                    "eff_end_date": None,
                    "is_current": 1,
                }
            ]
            continue

        # find version covering s_date
        covering = None
        for v in versions:
            start = v["eff_start_date"]
            end = v["eff_end_date"]
            if start <= s_date and (end is None or s_date < end):
                covering = v
                break

        if covering is None:
            # s_date earlier than earliest version's start
            f = min(versions, key=lambda x: x["eff_start_date"])
            versions.append(
                {
                    "plan": s_plan,
                    "eff_start_date": s_date,
                    "eff_end_date": f["eff_start_date"],
                    "is_current": 0,
                }
            )
        else:
            if _plans_equal(covering["plan"], s_plan):
                pass
            elif s_date == covering["eff_start_date"]:
                covering["plan"] = s_plan
            else:
                versions.append(
                    {
                        "plan": s_plan,
                        "eff_start_date": s_date,
                        "eff_end_date": covering["eff_end_date"],
                        "is_current": covering["is_current"],
                    }
                )
                covering["eff_end_date"] = s_date
                covering["is_current"] = 0

    # build output rows
    out_rows = []
    for acc, versions in account_versions.items():
        for v in versions:
            out_rows.append(
                {
                    "account_id": acc,
                    "plan": v["plan"],
                    "eff_start_date": v["eff_start_date"],
                    "eff_end_date": v["eff_end_date"],
                    "is_current": v["is_current"],
                }
            )

    out_df = pd.DataFrame(
        out_rows,
        columns=["account_id", "plan", "eff_start_date", "eff_end_date", "is_current"],
    )

    if not out_df.empty:
        out_df = out_df.sort_values(
            by=["account_id", "eff_start_date"], kind="stable"
        ).reset_index(drop=True)

    # restore dtypes to match original DIM_ACCOUNT conventions
    out_df["account_id"] = out_df["account_id"].astype(dim["account_id"].dtype, errors="ignore")
    out_df["is_current"] = out_df["is_current"].astype(dim["is_current"].dtype, errors="ignore")

    return {"dim_account_out": out_df}
